yes!<br><br>it can be used to reduce the loop levels. Taking a look on the code that <br>I send in previous e-mail, it still wrong... At each level a new formula <br>object need to be created as the previous one updated.<br><br>Using the Havard idea we have:<br><br><br>n &lt;- 100; p &lt;- 3; set.seed(123)<br>X &lt;- cbind(1, matrix(runif(n*p), n))<br>colnames(X) &lt;- paste(&#39;x&#39;, 0:p, sep=&#39;&#39;)<br>s = arima.sim(n=n, model=list(ar=0.9), sd=0.5)<br>u = rnorm(n, 0, 0.3)<br>z &lt;- runif(n)<br>s.z = arima.sim(n=n, model=list(ar=0.7), sd=0.3)<br>y = X%*%c(-1:1,0) + u + s + z*s.z<br><br>round(coef(summary(lm(y~0+s+ssz+X,<br>                       data.frame(y,s,ssz=s.z*z,X)))), 4)<br><br>jx = cbind(1, as.matrix(do.call(&#39;expand.grid&#39;,<br>     lapply(1:p, function(p) 0:1))))<br><br>file.res &lt;- &#39;~/dic-all-models.txt&#39;<br>cat(&#39;s&#39;,&#39;sz&#39;, colnames(X)[-1], &#39;dic
&#39;, file=file.res)<br>form0 = y ~ 0 + ff<br><br>require(INLA)<br><br>for (s in 0:1) {<br>     form.s = form0<br>     if (s==1)<br>         form.s = update(form0, &#39;.~.+f(s, model=&quot;ar1&quot;)&#39;)<br>     for (sz in 0:1) {<br>         <a href="http://form.sz" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://form.sz&amp;source=gmail&amp;ust=1792446519060000&amp;usg=AOvVaw3mSvRl6bca4FsOaBsqCTvf">form.sz</a> = form.s<br>         if (sz==1)<br>             <a href="http://form.sz" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://form.sz&amp;source=gmail&amp;ust=1792446519060000&amp;usg=AOvVaw3mSvRl6bca4FsOaBsqCTvf">form.sz</a> = update(<a href="http://form.sz" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://form.sz&amp;source=gmail&amp;ust=1792446519060000&amp;usg=AOvVaw3mSvRl6bca4FsOaBsqCTvf">form.sz</a>, &#39;.~.+f(sz, z, model=&quot;ar1&quot;)&#39;)<br>         for (j in 1:nrow(jx)) {<br>             dtemp &lt;- list(y=y, s=1:n, sz=1:n, z=z,<br>                           ff=X[,which(jx[j,]==1)])<br>             res = inla(<a href="http://form.sz" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://form.sz&amp;source=gmail&amp;ust=1792446519060000&amp;usg=AOvVaw3mSvRl6bca4FsOaBsqCTvf">form.sz</a>, data=dtemp,<br>                 control.compute=list(dic=TRUE))<br>             cat(s, sz, jx[j,-1], res$dic$dic,<br>                 &#39;
&#39;, file=file.res, append=TRUE)<br>             cat(s, sz, jx[j,-1], res$dic$dic, &#39;
&#39;)<br>         }<br>     }<br>}<br><br>ddic = read.table(file.res, header=TRUE)<br>fo = update(dic ~ s + sz,<br>  paste(&#39;.~.+&#39;, paste(colnames(X)[-1], collapse=&#39;+&#39;)))<br>round(coef(summary(lm(fo, ddic))), 4)<br><br>
